oxy_webhelp_navlinks = {"tocId-d39536e31116":{"topics":[{"title":"Viewing OpenStack Glance images","shortdesc":"<p class=\"shortdesc\">View the Glance images available in your onboarded OpenStack environments to assess         their protection status and locate images for snapshot or recovery operations.<\/p>","href":"openstack\/viewing_openstack_glance_images.html","attributes":{"data-id":"viewing_openstack_glance_images"},"menu":{"hasChildren":false},"tocID":"viewing_openstack_glance_images-d39536e31117","topics":[]},{"title":"Taking a snapshot of an OpenStack Glance image","shortdesc":"<p class=\"shortdesc\">Take an on-demand snapshot of an OpenStack Glance image to capture an immediate         recovery point for the boot image, independent of the SLA Domain schedule.<\/p>","href":"openstack\/taking_ods_openstack_glance_image.html","attributes":{"data-id":"taking_ods_openstack_glance_image"},"menu":{"hasChildren":false},"tocID":"taking_ods_openstack_glance_image-d39536e31128","topics":[]},{"title":"OpenStack Glance image details","shortdesc":"<p class=\"shortdesc\">The OpenStack Glance image details page displays the protection status,         configuration, and snapshot history for a specific Glance image.<\/p>","href":"openstack\/openstack_glance_image_details.html","attributes":{"data-id":"openstack_glance_image_details"},"menu":{"hasChildren":false},"tocID":"openstack_glance_image_details-d39536e31139","topics":[]}]}};